    h = observation.get("grid_height", 0)
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (-999, -999))
    resources = observation.get("resources", [])
    obstacles = set(tuple(p) for p in observation.get("obstacles", []))
    self_path = set(tuple(p) for p in observation.get("self_path", []))
    opp_path = set(tuple(p) for p in observation.get("opponent_path", []))
    blocked = obstacles | self_path
    if isinstance(observation.get("opponent_path"), (list, tuple)):
