        elif isinstance(r, (list, tuple)) and len(r) >= 2:
            res.append((int(r[0]), int(r[1])))

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best = (0, 0)
    best_score = -10**9

    for dx, dy in moves:
